import{_ as s,o as e,c as t,a2 as n}from"./chunks/framework.DDt0GYh1.js";const u=JSON.parse('{"title":"Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1794305854000}'),i={name:"guide.md"};function o(d,a,l,r,p,h){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="guide" tabindex="-1">Guide <a class="header-anchor" href="#guide" aria-label="Permalink to &quot;Guide&quot;">​</a></h1><p>A stripped-down crond clone in Go that reads a crontab, runs matching jobs each minute, and logs to stdout.</p><p>](<a href="https://mediuswareltd.github.io/pro-cron/" target="_blank" rel="noreferrer">https://mediuswareltd.github.io/pro-cron/</a>)</p><p>A minimal cron daemon written in Go — a stripped-down clone of <code>crond</code> that does exactly what you need and nothing more.</p><p>It reads a crontab file, wakes up at the top of every minute, and fires off any commands whose schedule matches the current time. No databases, no C dependencies, no root required.</p><hr><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li>You write a crontab file (same syntax as classic Unix cron).</li><li>You start <code>pro-cron</code> pointing at that file.</li><li>It runs in the foreground, fires jobs at the right time, and logs everything to stdout.</li><li>Send <code>SIGHUP</code> (Linux/macOS) to reload the crontab without restarting.</li></ol><hr><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p>You need Go 1.21 or newer.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pro-cron</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/pro-cron</span></span></code></pre></div><p>That&#39;s it — one binary, zero external dependencies.</p><hr><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pro-cron [-f /path/to/crontab]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Flag</th><th>Default (Linux/macOS)</th><th>Default (Windows)</th><th>Description</th></tr></thead><tbody><tr><td><code>-f</code></td><td><code>~/.pro-cron</code></td><td><code>%USERPROFILE%\\pro-cron.tab</code></td><td>Path to your crontab file</td></tr></tbody></table><h3 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pro-cron</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/pro-cron</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copy the example crontab and edit it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pro-cron.proc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.pro-cron</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Start the daemon</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./pro-cron</span></span></code></pre></div><h3 id="run-in-the-background-linux-macos" tabindex="-1">Run in the background (Linux/macOS) <a class="header-anchor" href="#run-in-the-background-linux-macos" aria-label="Permalink to &quot;Run in the background (Linux/macOS)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nohup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./pro-cron</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /var/log/pro-cron.log &amp;</span></span></code></pre></div><h3 id="run-on-windows" tabindex="-1">Run on Windows <a class="header-anchor" href="#run-on-windows" aria-label="Permalink to &quot;Run on Windows&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Start-Process</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FilePath </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.\\pro-cron.exe&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WindowStyle </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Hidden</span></span></code></pre></div><hr><h2 id="crontab-format" tabindex="-1">Crontab format <a class="header-anchor" href="#crontab-format" aria-label="Permalink to &quot;Crontab format&quot;">​</a></h2><p>The format is the classic five-field cron syntax:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────── minute       (0–59)</span></span>
<span class="line"><span>│  ┌─────────── hour         (0–23)</span></span>
<span class="line"><span>│  │  ┌────────── day of month (1–31)</span></span>
<span class="line"><span>│  │  │  ┌───────── month        (1–12)</span></span>
<span class="line"><span>│  │  │  │  ┌──────── day of week  (0–6, 0 = Sunday)</span></span>
<span class="line"><span>│  │  │  │  │</span></span>
<span class="line"><span>*  *  *  *  *  command to run</span></span></code></pre></div><p>Each field accepts:</p><table tabindex="0"><thead><tr><th>Syntax</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>*</code></td><td>every value</td><td><code>*</code> = every minute</td></tr><tr><td><code>n</code></td><td>exact value</td><td><code>5</code> = at minute 5</td></tr><tr><td><code>a-b</code></td><td>range</td><td><code>1-5</code> = Monday through Friday</td></tr><tr><td><code>*/n</code></td><td>every n steps</td><td><code>*/15</code> = every 15 minutes</td></tr><tr><td><code>a-b/n</code></td><td>range with step</td><td><code>0-30/5</code> = 0, 5, 10, …, 30</td></tr><tr><td><code>a,b,c</code></td><td>list</td><td><code>1,3,5</code> = minutes 1, 3, and 5</td></tr></tbody></table><p>Fields can be combined: <code>0,30 9-17 * * 1-5</code> means &quot;at :00 and :30, during 9 AM–5 PM, weekdays.&quot;</p><h3 id="special-keywords" tabindex="-1">Special keywords <a class="header-anchor" href="#special-keywords" aria-label="Permalink to &quot;Special keywords&quot;">​</a></h3><p>These are shorthand for common schedules:</p><table tabindex="0"><thead><tr><th>Keyword</th><th>Equivalent</th></tr></thead><tbody><tr><td><code>@reboot</code></td><td>Once, when the daemon starts</td></tr><tr><td><code>@hourly</code></td><td><code>0 * * * *</code></td></tr><tr><td><code>@daily</code> / <code>@midnight</code></td><td><code>0 0 * * *</code></td></tr><tr><td><code>@weekly</code></td><td><code>0 0 * * 0</code></td></tr><tr><td><code>@monthly</code></td><td><code>0 0 1 * *</code></td></tr><tr><td><code>@yearly</code> / <code>@annually</code></td><td><code>0 0 1 1 *</code></td></tr></tbody></table><h3 id="comments-and-blank-lines" tabindex="-1">Comments and blank lines <a class="header-anchor" href="#comments-and-blank-lines" aria-label="Permalink to &quot;Comments and blank lines&quot;">​</a></h3><p>Lines starting with <code>#</code> are comments. Blank lines are ignored.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># This is a comment</span></span>
<span class="line"><span>* * * * * echo &quot;every minute&quot;</span></span></code></pre></div><hr><h2 id="example-crontab" tabindex="-1">Example crontab <a class="header-anchor" href="#example-crontab" aria-label="Permalink to &quot;Example crontab&quot;">​</a></h2><div class="language-cron vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cron</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Ping a health-check endpoint every 5 minutes</span></span>
<span class="line"><span>*/5 * * * * curl -s https://example.com/health</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Back up the database every night at 2:30 AM</span></span>
<span class="line"><span>30 2 * * * /usr/local/bin/backup.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Send a weekly digest every Monday at 9 AM</span></span>
<span class="line"><span>0 9 * * 1 /usr/local/bin/weekly-report.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Run once on daemon startup</span></span>
<span class="line"><span>@reboot /usr/local/bin/init.sh</span></span></code></pre></div><hr><h2 id="reloading-the-crontab" tabindex="-1">Reloading the crontab <a class="header-anchor" href="#reloading-the-crontab" aria-label="Permalink to &quot;Reloading the crontab&quot;">​</a></h2><p>Edit your crontab file, then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux / macOS — send SIGHUP to the running daemon</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">kill</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -HUP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgrep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pro-cron</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>On Windows there is no SIGHUP. Just stop and restart the daemon after editing the file.</p><hr><h2 id="logging" tabindex="-1">Logging <a class="header-anchor" href="#logging" aria-label="Permalink to &quot;Logging&quot;">​</a></h2><p>All output goes to <strong>stdout</strong> in a simple, readable format:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[pro-cron] 2026/03/18 09:00:00 daemon started (pid 12345), crontab: /home/user/.pro-cron</span></span>
<span class="line"><span>[pro-cron] 2026/03/18 09:00:00 loaded 4 job(s)</span></span>
<span class="line"><span>[pro-cron] 2026/03/18 09:00:01 start  | /usr/local/bin/backup.sh</span></span>
<span class="line"><span>[pro-cron] 2026/03/18 09:00:03 output | Backup complete: 42 MB</span></span>
<span class="line"><span>[pro-cron] 2026/03/18 09:00:03 done   | /usr/local/bin/backup.sh</span></span></code></pre></div><p>To write logs to a file, redirect stdout when starting:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./pro-cron</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /var/log/pro-cron.log</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;&amp;1</span></span></code></pre></div><hr><h2 id="what-it-does-not-do" tabindex="-1">What it does NOT do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does NOT do&quot;">​</a></h2><p>A few things the classic <code>crond</code> handles that <code>pro-cron</code> intentionally skips to stay minimal:</p><ul><li><strong>No mail delivery</strong> — job output is logged, not emailed.</li><li><strong>No per-user crontabs</strong> — one crontab file, one daemon.</li><li><strong>No environment variable definitions</strong> inside the crontab (<code>VAR=value</code> lines are not supported).</li><li><strong>No second-level precision</strong> — minimum interval is one minute.</li></ul><p>If you need any of these, consider using the system <code>crond</code> or a more full-featured scheduler.</p><hr><h2 id="signals" tabindex="-1">Signals <a class="header-anchor" href="#signals" aria-label="Permalink to &quot;Signals&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Signal</th><th>Effect</th></tr></thead><tbody><tr><td><code>SIGTERM</code> / <code>SIGINT</code> / <code>Ctrl-C</code></td><td>Graceful shutdown</td></tr><tr><td><code>SIGHUP</code></td><td>Reload crontab file (Linux/macOS only)</td></tr></tbody></table><hr><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>MIT</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p>Full docs site (VitePress): <strong><a href="https://mediuswareltd.github.io/pro-cron/" target="_blank" rel="noreferrer">https://mediuswareltd.github.io/pro-cron/</a></strong></p><p>Local preview:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span></code></pre></div><hr><p>Repository: <a href="https://github.com/mediuswareltd/pro-cron" target="_blank" rel="noreferrer">mediuswareltd/pro-cron</a></p>`,67)])])}const k=s(i,[["render",o]]);export{u as __pageData,k as default};
